insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('mei-goeoedbeidl-is-wia-i-chronisch-laeaea-owa-volla-hoffnung', 'Mei Göödbeidl is wia I - chronisch lääa, owa volla Hoffnung!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mein Geldbeutel ist wie ich – chronisch leer, aber voller Hoffnung!', '[{"kategorie": "wörtlich", "text": "\"Mein Portemonnaie ist wie ich – chronisch leer, aber voller Hoffnung!\"  2. Ich bin wie mein Geldbeutel – flach, leer und ständig auf der Suche nach Kleingeld!  3. Mein Geldbeutel ist wie mein Humor: schwarz, leer und leicht beleidigt!"}]'::jsonb, ''),
  ('waarad-i-a-reicha-goeoedbeidl-haed-i-ma-schoo-laengsd-bessare-freind-kaufd-ois-eich', 'Waarad I a reicha Göödbeidl, häd I ma schoo längsd bessare Freind kaufd ois eich!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wäre ich ein reicher Geldbeutel, dann hätt ich mir schon längst bessere Freunde gekauft als euch!', '[{"kategorie": "wörtlich", "text": "\"Wäre ich ein Geldscheißer, hätte ich mir schon längst einen besseren Freundeskreis gekauft!\"  2. \"Wenn ich ein reicher Geldsack, würd ich mir bessere Leute als Freunde leisten!\"  3. \"Als Großverdiener mit genug Kohle hätt ich mir die Runde hier längst ausgetauscht!\""}]'::jsonb, ''),
  ('mei-beidlschniira-sitzt-so-eng-dass-i-noamal-zwa-oktavn-heecha-reedn-miassad', 'Mei Beidlschniira sitzt so eng, dass I noamal zwa Oktavn heecha reedn miassad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Beutelschnürer sitzt so eng, dass ich normal zwei Oktaven höher reden müsste!', '[{"kategorie": "wörtlich", "text": "\"Mein Sackschnürer sitzt so eng, dass ich eigentlich zwei Oktaven höher reden müsste!\"  2. \"Meine Unterhose sitzt so eng, dass ich normalerweise zwei Oktaven höher sprechen müsste!\"  3. \"Mein Pimmelquetscher sitzt so stramm, ich müsste eigentlich klingen wie ''ne singende Micky Maus auf Speed!"}]'::jsonb, ''),
  ('fia-sei-beidlmattn-brauchsd-a-macheetn', 'Fia sei Beidlmattn brauchsd a Macheetn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Für seine Beutelmatte brauchst du ''ne Machete!', '[{"kategorie": "wörtlich", "text": "\"Für seinen Beutelbewuchs brauchst du ''ne Machete, um bis zum Pimmel vorzudringen!\"  2. Sein Liebesdschungel ist so dicht - da hast du ohne Buschmesser keine Chance!  3. Bevor du da rankommst, musst du dich erst durch seine Beutelmatte hacken!"}]'::jsonb, ''),
  ('dea-typ-is-a-echta-beidlrotz-pickd-auf-dia-wiara-feichta-sockn-im-hochsomma', 'Dea Typ is a echta Beidlrotz - pickd auf dia wiara feichta Sockn im Hochsomma!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Typ ist eine echte Sackratte – pickt an dir wie ‘n feuchter Socken im Hochsommer!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist eine echte Sackratte – klebt an dir wie ein feuchter Socken im Hochsommer!\"  2. Der ist eine Sackratte deluxe - klebt an dir wie ein Klopapierfetzen unterm Schuh!  3. Dieser Typ ist ein widerlicher Plagegeist - hockt auf dir wie ein Kaugummi im Brusthaar!"}]'::jsonb, ''),
  ('i-hob-glaubd-es-juckd-vua-aufregung-dabei-woas-a-beidlrotz', 'I hob glaubd, es juckd vua Aufregung, dabei woas a Beidlrotz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich habe geglaubt, es juckt vor Aufregung, dabei waren''s Sackratten!', '[{"kategorie": "wörtlich", "text": "\"Ich dachte, es juckt vor Aufregung, dabei waren es Filzläuse!\"  2. Ich dachte, das Kribbeln ist Vorfreude - doch leider war''s ''ne Lausparty im Intimbereich!  3. Am Ende musste ich mir eingestehen: Das Kribbeln kam nicht von Emotionen, sondern von Läusen!"}]'::jsonb, ''),
  ('a-beidlrotz-is-a-klaana-blutsauga-2-3mm-grooss-und-woond-in-da-schaamhoageegnd-waunnsd-da-sowos-eifaungsd-host-deina-oidn-wos-z-beichtn', 'A Beidlrotz is a klaana Blutsauga, 2-3mm grooss und woond in da Schaamhoageegnd - waunnsd da sowos eifaungsd, host deina Oidn wos z''beichtn!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ein Beidlratz ist ein Blutsauger, 2–3 mm groß und wohnt in der Schamhaargegend - wenn du dir sowas einfängst, hast du deiner Frau was zu beichten!', '[{"kategorie": "wörtlich", "text": "\"Die Flizlaus ist ein Blutsauger, 2–3 mm groß und wohnt in der Schamhaargegend - wenn du dir sowas einfängst, hast du deiner Frau was zu beichten!\"  2. \"Die Filzlaus ist ein winziger Blutsauger im Schambereich – und wer sie hat, schuldet zu Hause eine Erklärung!\"  3. \"Die Filzlaus lebt im Schamhaar und ernährt sich von Blut - der Befund ist meist nicht nur medizinisch relevant, denn plötzlich gibt''s auch zu Hause Redebedarf!\""}]'::jsonb, ''),
  ('da-leimbeidl-baud-da-an-schraunk-dea-hoid-eewich-nua-leida-dauads-a-eewich', 'Da Leimbeidl baud da an Schraunk, dea hoid eewich - nua leida dauads a eewich!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Leimbeitel baut dir einen Schrank, der hält ewig - nur leider daúert''s auch ewig!', '[{"kategorie": "wörtlich", "text": "\"Der Tischler baut dir einen Schrank, der hält ewig - nur leider daúert''s auch ewig!\"  2. Was der Tischler baut, hält für Generationen – aber du brauchst auch Generationen, bis es fertig ist!  3. Ein Tischlerschrank steht für die Ewigkeit – sobald er endlich steht!"}]'::jsonb, ''),
  ('da-wei-schmeckd-wiara-beidlwossa', 'Da Wei schmeckd wiara Beidlwossa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Wein schmeckt wie ein Beutelwasser', '[{"kategorie": "wörtlich", "text": "\"Der Wein schmeckt wie Pimmelwasser!\"  2. (scherzhaft für): \"Das ist kein Wein, das ist Abwaschwasser!\"  3. Dieser Wein ist nicht zum Saufen!  4. [[Da Wei is a Gschloda!]]"}]'::jsonb, ''),
  ('des-is-kaa-kaffee-des-is-a-beidlwossa-mit-mueuechschaum', 'Des is kaa Kaffee - des is a Beidlwossa mit Müüchschaum!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Das is kein Kaffee, das ist ein Beidlwasser mit Milchschaum!', '[{"kategorie": "wörtlich", "text": "\"Das is kein Kaffee, das ist Pimmelwasser mit Milchschaum!\"  2. Der Kaffee schmeckt wie aufgekochtes Rasierwasser mit Milchhauberl!  3. Des is Barista-Beschiss mit Beidlwossa-Geschmack!"}]'::jsonb, ''),
  ('des-bia-trinkt-si-wiara-beidlwossa-noch-10-hoibe-host-no-imma-kan-sitzn', 'Des Bia trinkt si wiara Beidlwossa - noch 10 Hoibe host no imma kan sitzn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Das Bier trinkt sich wie Beidlwasser - nach 10 Halben hat man noch immer keinen sitzen!', '[{"kategorie": "wörtlich", "text": "\"Das Bier trinkt sich wie Pimmelwasser - nach 10 Halben hat man noch immer keinen sitzen!\"  2. Das Bier ist der reinste [[Fensterschwitz]] - nach 10 Halben bist noch immer nüchtern wie ein Beamter!  3. Des Dünnbier schmeckt wia Beidlwossa - I wea imma niachtana, je mea I trink!\""}]'::jsonb, ''),
  ('fias-dressing-neema-in-soft-von-ana-frischn-lemoni-und-a-wengl-senf', 'Fias Dressing neema in Soft von ana frischn Lemoni und a wengl Senf!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Für das Dressing nehmen wir den Saft von einer frischen Lemoni und ein wenig Senf!', '[{"kategorie": "wörtlich", "text": "\"Fürs Dressing nehmen wir einfach nur frischen Zitronensaft und ein bisschen Senf!\"  2. Zitronensaft und ein Klecks Senf – mehr brauchst du nicht fürs Dressing!  3. Ein Spritzer frischer Zitrone und eine Spur Senf verleihen dem Dressing seine feine Würze!"}]'::jsonb, ''),
  ('mit-dem-lemoniwassal-kaunnst-ned-amoi-mea-de-bleamaln-giassn', 'Mit dem Lemoniwassal kaunnst ned amoi mea de Bleamaln giassn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit diesem Lemoniwasserl kannst du nicht mal mehr Blümchern gießen!', '[{"kategorie": "wörtlich", "text": "\"Dieses Zitronenwässerchen ist selbst fürs Blumengießen zu schal!\"  2. Dieses Zitronenwässerchen ist so schal und geschmacklos, dass es nicht mal als Gießwasser für die Blumen taugt!  3. Gieß mit dem Zeug a Blume – und sie stirbt!"}]'::jsonb, ''),
  ('dea-huanbeidl-kennt-mea-schloofzimma-ois-postleitzoin', 'Dea Huanbeidl kennt mea Schloofzimma ois Postleitzoin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Hurenbeutel kennt mehr Schlafzimmer als Postleitzahlen!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hurensack kennt mehr Schlafzimmer als Postleitzahlen!\"  2. Dieser notorische Fremdgeher kennt mehr Schlafzimmer als Postleitzahlen!  3. Wenn Seitensprünge olympisch wären, hätt dieser Hurenbeidl schon fünf Goldene!"}]'::jsonb, ''),
  ('dea-huanbeidl-liagt-da-mittn-ins-gsicht-und-wueue-daunn-aa-noo-a-bakschisch', 'Dea Huanbeidl liagt da mittn ins Gsicht – und wüü daunn aa noo a Bakschisch!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der Hurenbeutel lügt dir mitten ins Gesicht – und will dann auch noch ein Trinkgeld!', '[{"kategorie": "wörtlich", "text": "\"Dieser hinterfotzige Gauner lügt dir mitten ins Gesicht – und will dann auch noch ein Trinkgeld!\"  2. Der Drecksgauner schaut dir beim Lügen auch noch tief in die Augen – und streckt dann die Hand aus!  3. Dieser miese Halunke belügt dich unverfroren – und verlangt dann auch noch Trinkgeld dafür!"}]'::jsonb, ''),
  ('de-politika-san-olle-huanbeidln', 'De Politika san olle Huanbeidln!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Die Politiker sind alle Hurenbeutel!', '[{"kategorie": "wörtlich", "text": "\"Die Politiker sind allesamt Hurensäcke!\" 2. Die Politiker sind durch die Bank nur falsche Halunken!  3. Alle Politiker sind hinterfotzige Gauner!"}]'::jsonb, ''),
  ('dea-huanbeidl-hod-ia-a-dickpik-gschickd', 'Dea Huanbeidl hod ia a Dickpik gschickd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Dieser Hurenbeutel hat ihr ein ''Dickpic'' geschickt!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hurensack hat ihr ein Penisfoto geschickt!\"  2. Dieser notgeile Vollpfosten hat ihr ein Schwanzfoto geschickt!  3. Dieser versaute Mistkerl hat ihr ein Foto von seinem besten Stück geschickt!"}]'::jsonb, ''),
  ('du-huanbeidl', 'Du Huanbeidl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du Hurenbeutel!', '[{"kategorie": "allg.", "text": "Du hinterfotziger Gauner!  2. Du falscher Halunke!  3. Du Mistkerl!  4. Du [[Scheissheisl]]!"}]'::jsonb, ''),
  ('dea-huanbeidl-kauft-si-a-buanheidl', 'Dea Huanbeidl kauft si a Buanheidl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Hurenbeidl kauft sich ein Burenheidl', '[{"kategorie": "wörtlich", "text": "\"Dieser Hurenbeutel kauft sich ein Burenhäutel\" [scherzhafter Schüttelreim mit den beiden Wörtern \"Hurenbeutel\" (\"Hurenpimmel\") und \"Burenhäutel\" (\"Burenwurst\")]"}, {"kategorie": "", "text": "\"Dieser Saubeutel kauft sich ein Burenhäutel!\"  3. \"Dieses Hurenwürstchen kauft sich ein Burenwürstchen!\""}]'::jsonb, ''),
  ('dea-saubeidl-haengd-sei-futroschpae-iwaroi-eine', 'Dea Saubeidl hängd sei Futroschpä iwaroi eine!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieser Saubeutel hängt seine Futraspel überall rein!', '[{"kategorie": "wörtlich", "text": "\"Dieser Sausack hängt seine Votzenraspel überall rein!\"  2. Dieser Lustmolch hängt seinen Pimmel überall rein!  3. Dieser triebgesteuerte Schürzenjäger steckt sein Rohr in alles, was kein Schloss hat!"}]'::jsonb, ''),
  ('so-a-saubeidl-schdueued-das-bia-und-sogt-no-du-soist-weniga-saufn', 'So a Saubeidl - schdüüd das Bia und sogt no, du soist weniga saufn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'So ein Saubeutel - stiehlt dir das Bier und sagt noch, du sollst weniger saufen!', '[{"kategorie": "wörtlich", "text": "\"So ein Sausack - stiehlt dir das Bier und sagt noch, du sollst weniger saufen!\"  2. Unverschämter Halunke – klaut dein Bier und predigt dir dann auch noch Abstinenz!  3. So ein Dreckskerl – macht dir das Bier streitig und spielt dann auch noch den Moralapostel obendrauf!"}]'::jsonb, ''),
  ('dea-saubeidl-ruelpst-in-da-kiachn-und-sogt-daunn-aa-noo-amen', 'Dea Saubeidl rülpst in da Kiachn und sogt daunn aa noo ''Amen''!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Saubeutel rülpst in der Kirche und sagt dann auch noch ''Amen''!', '[{"kategorie": "wörtlich", "text": "\"Dieser versaute Sack rülpst in der Kirche und sagt dann auch noch ''Amen''!\"  2. Dieser ungehobelte Lümmel rülpst im Gotteshaus und sagt dann auch noch ''Amen''!\"  2. Dieser gottlose Dreckslappen rülpst in die Liturgie und sagt dann auch noch fromm ''Amen''!  3. Dieser schamlose Dreckskerl rülpst in die Predigt und murmelt dann auch noch scheinheilig ''Amen''!\""}]'::jsonb, ''),
  ('du-gschissana-saubeidl', 'Du gschissana Saubeidl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du g''schissener Saubeutel!', '[{"kategorie": "wörtlich", "text": "\"Du räudiger Schweinepimmel!\"  2. \"Du verdammtes Dreckschwein!\"  3. \"Du verkommenes Saugfraßt!\""}]'::jsonb, ''),
  ('dea-schweinsbeidl-losst-mittn-im-aufzug-an-schaas-und-schreit-daunn-aa-no-halleluja', 'Dea Schweinsbeidl losst mittn im Aufzug an Schaas und schreit daunn aa no ''Halleluja''!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Schweinsbeutel lässt mitten im Aufzug einen Schas und schreit dann auch noch ''Halleluja''!', '[{"kategorie": "wörtlich", "text": "\"Dieser versaute Depp furzt mitten im Aufzug und schreit dann auch noch ''Halleluja''!\"  2. Dieser schamlose Dreckskerl lässt mitten im Aufzug einen fahren und schreit dann auch noch ''Halleluja''!  3. Dieser schamlose Vollpfosten lässt mitten im Fahrstuhl einen krachen und segnet’s dann auch noch mit einem ''Halleluja''!"}]'::jsonb, ''),
  ('dea-oelendige-schweinsbeidl-ziagd-mi-jedes-moi-iwan-tisch', 'Dea ölendige Schweinsbeidl ziagd mi jedes Moi iwan Tisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der elendige Schweinsbeutel zieht mich jedes Mal über den Tisch!', '[{"kategorie": "wörtlich", "text": "\"Dieser elendige Sausack zieht mich jedes Mal über den Tisch!\"  2. Dieser hundsgemeine Lump legt mich jedes Mal aufs Kreuz!  3. Dieser hinterfotzige Drecksach trickst mich jedes Mal aufs Neue aus!"}]'::jsonb, ''),
  ('schleichds-eich-es-schweinskrippaen', 'Schleichds eich, es Schweinskrippän!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Schleicht euch, ihr Schweinskrüppeln!', '[{"kategorie": "wörtlich", "text": "\"Verpisst euch, ihr Saukrüppel!\"  2. Haut ab, ihr degenerierten Schweinskrüppel!  3. Verzupft euch, ihr grindigen Saukerle!"}]'::jsonb, ''),
  ('dea-schdiabeidl-ruaft-dreimoi-noo-a-runde-zoid-daunn-owa-ned', 'Dea Schdiabeidl ruaft dreimoi ''Noo a Runde!'', zoid daunn owa ned!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Stierbeutel ruft dreimal ''Noch eine Runde!'', zahlt dann aber nicht!', '[{"kategorie": "wörtlich", "text": "\"Dieser Großkotz ruft dreimal ''Noch eine Runde!'', zahlt dann aber nicht!\"  2. Dieser Saubazi bestellt eine Runde nach der anderen, zahlt aber keinen Cent!  3. Dieser hinterfotzige Drecksack bestellt drei Runden und ergreift vorm Zahlen die Flucht!"}]'::jsonb, ''),
  ('dea-schdiabeidl-schdiad-ma-schdaendig-ins-dekollete', 'Dea Schdiabeidl schdiad ma schdändig ins Dekolleté!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieser Stierbeutel stiert mir ständig ins Dekolleté!', '[{"kategorie": "wörtlich", "text": "\"Dieser notgeile Stier glotzt mir ständig ins Dekolleté!\"  2. Dieser stiergeile Lüstling starrt mir dauernd auf die Hupen!  3. Dieser schmierige Geilbock glotzt andauernd auf meinen Busen!"}]'::jsonb, ''),
  ('dea-schdiabeidl-brunzt-mittn-aufd-gossn', 'Dea Schdiabeidl brunzt mittn aufd Gossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Stierbeutel brunzt mitten auf die Gasse!', '[{"kategorie": "wörtlich", "text": "\"Dieser versaute Dreckskerl pinkelt mitten auf die Straße!\"  2. Dieser schamlose Mistkerl erleichtert sich mitten auf der Straße!  3. Dieser ungehobelte Lümmel lässt mitten auf der Straße die Hose runter und pinkelt ganz ungeniert!"}]'::jsonb, ''),
  ('du-schdiabeidl-du-vasauta', 'Du Schdiabeidl, du vasauta!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du Stierbeutel, du versauter!', '[{"kategorie": "wörtlich", "text": "\"Du Stierpimmel, du versauter!\"  2. \"Du lüsterner Dreckskerl!\"  3. \"Du räudiger Lustmolch!\""}]'::jsonb, ''),
  ('du-schwoazgsoeoechde-hundshaut', 'Du schwoazgsööchde Hundshaut!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schwarzgeselchte Hundshaut!', '[{"kategorie": "wörtlich", "text": "\"Du schwarzgeräucherte Hundshaut!\"  2. (fig.) Du hundsgemeiner Lump!  3. Du verdammter [[Hundsbeidl]]!"}]'::jsonb, ''),
  ('glaenzn-wiara-gwetzda-hundsbeidl', 'glänzn wiara gwetzda Hundsbeidl', '', '', '', 'Wiener Sprüche, die sitzen!', 'glänzen wie ein gewetzter Hundebeutel', '[{"kategorie": "wörtlich", "text": "\"glänzen wie ein polierter Hundepimmel\""}, {"kategorie": "allg.", "text": "vor Sauberkeit glänzen, strahlen, funkeln"}, {"kategorie": "", "text": "strahlend sauber sein, funkeln vor Reinheit"}]'::jsonb, 'Waunn d''Oma putzd, glänzd d''Kuchl wiara gwetzda Hundsbeidl!'),
  ('glaenzn-wiara-gwixda-hundsbeidl', 'glänzn wiara gwixda Hundsbeidl', '', '', '', 'Wiener Sprüche, die sitzen!', 'glänzen wie ein gewichster Hundebeutel', '[{"kategorie": "wörtlich", "text": "\"glänzen wie ein polierter Hundepimmel\""}, {"kategorie": "allg.", "text": "vor Sauberkeit glänzen, strahlen, funkeln"}, {"kategorie": "", "text": "strahlend sauber sein, funkeln vor Reinheit"}]'::jsonb, ''),
  ('dea-hundsbeidl-braucht-an-jeedn-toog-wos-zum-wetzn', 'Dea Hundsbeidl braucht an jeedn Toog wos zum Wetzn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieser Hundsbeutel braucht jeden Tag etwas zum Wetzen!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hundskerl braucht täglich was zum Rammeln!\"  2. Dieser notgeile Dreckskerl muss jeden Tag jemanden flachlegen!  3. [[Dea]] Hundsbeidl braucht jedn Tog wos zum Wetzn!"}]'::jsonb, ''),
  ('so-a-hundsbeidl-braucht-taeglich-a-weibagschdoeoe-zum-reibm', 'So a Hundsbeidl braucht täglich a Weibagschdöö zum Reibm!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieser Hundsbeutel braucht täglich ein Weibergestell zum Wetzen!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hundskerl braucht täglich was zum Rammeln!\"  2. Dieser notgeile Dreckskerl muss jeden Tag jemanden flachlegen!  3. [[So]] a Hundsbeidl braucht täglich a Weibagschdöö zum Reibn!"}]'::jsonb, ''),
  ('dea-hundsbeidl-daeaedad-sogoa-in-pobst-des-papamobueue-flaadan', 'Dea Hundsbeidl däädad sogoa in Pobst des Papamobüü flaadan!', '', '', '', 'Wiener Gaunersprache', 'Dieser Hundsbeutel täte sogar dem Papst das Papamobil fladern!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hundskerl würde sogar dem Papst das Papamobil klauen!\"  2. Dieser hinterfotzige Halunke macht selbst vor Heiligem nicht Halt!  3. Der schamlose Dreckskerl würde dem Pfarrer sogar die Monstranz klauen und dann als Designerlampe verkaufen!"}]'::jsonb, ''),
  ('dea-hundsbeidl-hod-scho-wiida-in-mei-blumanbeetl-brunzt', 'Dea Hundsbeidl hod scho wiida in mei Blumanbeetl brunzt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Hundsbeutel hat schon wieder in mein Blumenbeet gebrunzt!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hundskerl hat schon wieder in mein Blumenbeet gepinkelt!\"  2. Schon wieder pisst mir dieser versaute Depp in mein Blumenbeet, als wär’s ein Freiluftpissoir!  3. Dieser schamlose Hundskerl glaubt doch tatsächlich, täglich mein Blumenbeet wässern zu dürfen!"}]'::jsonb, ''),
