  ('schweinsgfraasd-oelendiges', 'Schweinsgfraasd, ölendiges!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Schweinsgfraßt, elendiges!', '[{"kategorie": "wörtlich", "text": "\"Du elendes Saubiest!\"  2. \"Du mieses Dreckschwein!\"  3. \"Du widerwärtiges Miststück!\"  4. \"Du verdammtes Sauviech!\""}]'::jsonb, ''),
  ('des-schweinsgfraassd-losst-si-ned-eischoitn', 'Des Schweinsgfraassd losst si ned eischoitn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieses Schweinsgfraßt lässt sich nicht einschalten!', '[{"kategorie": "wörtlich", "text": "\"Dieses bockige Gerät lässt sich nicht einschalten!\"  2. Dieses störrische Gerät will einfach nicht starten!  3. Dieses widerspenstige Gerät lässt sich nicht überlisten!"}]'::jsonb, ''),
  ('dea-saubaazi-greifd-aana-jeedn-frau-aufd-duttln', 'Dea Saubaazi greifd aana jeedn Frau aufd Duttln!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieser Saubazi greift jeder Frau auf die Tutteln!', '[{"kategorie": "wörtlich", "text": "\"Dieser Saukerl greift jeder Frau an die Titten!\"  2. Dieser notgeile Grabscher greift jeder Frau ungefragt an die Möpse!  3. Dieser versaute Lustmolch tatscht alles an, was Brüste hat!"}]'::jsonb, ''),
  ('dea-saubaazi-hod-eam-de-freindin-ausgschbaunnd', 'Dea Saubaazi hod eam de Freindin ausgschbaunnd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Saubazi hat ihm die Freundin ausgespannt!', '[{"kategorie": "wörtlich", "text": "\"Dieser hundsgemeine Lump hat ihm die Freundin ausgespannt!\"  2. Dieser miese Dreckskerl hat ihm die Freundin weggeschnappt wie ein Geier das Aas!  3. Dieser hinterfotzige Drecksack hat ihm die Freundin abgeluchst!"}]'::jsonb, ''),
